3	import io.grpc.Metadata;
4	import io.quarkus.security.identity.request.AuthenticationRequest;
5	
6	/**
7	 * gRPC security mechanism based on gRPC call metadata
8	 *
9	 * To secure your gRPC endpoints, create a CDI bean implementing this interface.
10	 *
11	 * Make sure that an {@link io.quarkus.security.identity.IdentityProvider} for the {@link AuthenticationRequest}
12	 * returned by {@code createAuthenticationRequest} is available by adding a suitable extension to your application.
13	 *
14	 */
15	public interface GrpcSecurityMechanism {
16	    int DEFAULT_PRIORITY = 1000;
17	
18	    /**
19	     *
20	     * @param metadata metadata of the gRPC call
21	     * @return true if and only if the interceptor should handle security for this metadata. An interceptor may decide
22	     *         it should not be triggered for a call e.g. if some header is missing in metadata.
23	     */
24	    boolean handles(Metadata metadata);
25	
26	    /**
27	     *
28	     * @param metadata metadata of the gRPC call
29	     * @return authentication request based on the metadata
30	     */
31	    AuthenticationRequest createAuthenticationRequest(Metadata metadata);
32	
33	    default int getPriority() {
34	        return DEFAULT_PRIORITY;
35	    }
36	}
