144	    private void buildGrpcServer(Vertx vertx, GrpcServerConfiguration configuration, RuntimeValue<Router> routerSupplier,
145	            ShutdownContext shutdown, Map<String, List<String>> blockingMethodsPerService,
146	            Map<String, List<String>> virtualMethodsPerService,
147	            GrpcContainer grpcContainer, LaunchMode launchMode) {
148	
149	        GrpcServer server = GrpcServer.server(vertx);
150	        List<ServerInterceptor> globalInterceptors = grpcContainer.getSortedGlobalInterceptors();
151	
152	        if (launchMode == LaunchMode.DEVELOPMENT) {
153	            // add as last, so they will run first
154	            globalInterceptors.add(new DevModeInterceptor(Thread.currentThread().getContextClassLoader()));
155	            globalInterceptors.add(new GrpcHotReplacementInterceptor());
156	        }
157	
158	        List<GrpcServiceDefinition> toBeRegistered = collectServiceDefinitions(grpcContainer.getServices());
159	        List<ServerServiceDefinition> definitions = new ArrayList<>();
160	
161	        CompressionInterceptor compressionInterceptor = prepareCompressionInterceptor(configuration);
162	
163	        for (GrpcServiceDefinition service : toBeRegistered) {
164	            ServerServiceDefinition defWithInterceptors = serviceWithInterceptors(
165	                    vertx, grpcContainer, blockingMethodsPerService, virtualMethodsPerService, compressionInterceptor, service,
166	                    launchMode == LaunchMode.DEVELOPMENT);
167	            LOGGER.debugf("Registered gRPC service '%s'", service.definition.getServiceDescriptor().getName());
168	            ServerServiceDefinition serviceDefinition = ServerInterceptors.intercept(defWithInterceptors, globalInterceptors);
169	            GrpcServiceBridge bridge = GrpcServiceBridge.bridge(serviceDefinition);
170	            bridge.bind(server);
171	            definitions.add(service.definition);
172	        }
173	
174	        boolean reflectionServiceEnabled = configuration.enableReflectionService || launchMode == LaunchMode.DEVELOPMENT;
175	
176	        if (reflectionServiceEnabled) {
177	            LOGGER.info("Registering gRPC reflection service");
178	            ReflectionServiceV1 reflectionServiceV1 = new ReflectionServiceV1(definitions);
179	            ReflectionServiceV1alpha reflectionServiceV1alpha = new ReflectionServiceV1alpha(definitions);
180	            ServerServiceDefinition serviceDefinition = ServerInterceptors.intercept(reflectionServiceV1, globalInterceptors);
181	            GrpcServiceBridge bridge = GrpcServiceBridge.bridge(serviceDefinition);
182	            bridge.bind(server);
183	            ServerServiceDefinition serviceDefinitionAlpha = ServerInterceptors.intercept(reflectionServiceV1alpha,
184	                    globalInterceptors);
185	            GrpcServiceBridge bridgeAlpha = GrpcServiceBridge.bridge(serviceDefinitionAlpha);
186	            bridgeAlpha.bind(server);
187	        }
188	
189	        initHealthStorage();
190	
191	        LOGGER.info("Starting new Vert.x gRPC server ...");
192	        Route route = routerSupplier.getValue().route().handler(ctx -> {
193	            if (!isGrpc(ctx)) {
194	                ctx.next();
195	            } else {
196	                if (!Context.isOnEventLoopThread()) {
197	                    Context capturedVertxContext = Vertx.currentContext();
198	                    if (capturedVertxContext != null) {
199	                        capturedVertxContext.runOnContext(new Handler<Void>() {
200	                            @Override
201	                            public void handle(Void unused) {
202	                                server.handle(ctx.request());
203	                            }
204	                        });
205	                        return;
206	                    }
207	                }
208	                server.handle(ctx.request());
209	            }
210	        });
211	        shutdown.addShutdownTask(route::remove); // remove this route at shutdown, this should reset it
212	
213	        initHealthStorage();
214	    }
