222	    private void prodStart(GrpcContainer grpcContainer, Vertx vertx, GrpcServerConfiguration configuration,
223	            GrpcBuilderProvider<?> provider, Map<String, List<String>> blockingMethodsPerService,
224	            Map<String, List<String>> virtualMethodsPerService,
225	            LaunchMode launchMode) {
226	        CompletableFuture<Void> startResult = new CompletableFuture<>();
