228	        vertx.deployVerticle(
229	                () -> new GrpcServerVerticle(configuration, grpcContainer, provider, launchMode, blockingMethodsPerService,
230	                        virtualMethodsPerService),
231	                new DeploymentOptions().setInstances(configuration.instances),
232	                result -> {
233	                    if (result.failed()) {
