237	
238	                        startResult.complete(null);
239	                    }
240	                });
241	
242	        try {
243	            startResult.get(1, TimeUnit.MINUTES);
244	        } catch (InterruptedException e) {
245	            Thread.currentThread().interrupt();
246	            LOGGER.error("Unable to start the gRPC server, waiting for server start interrupted");
247	        } catch (TimeoutException e) {
248	            LOGGER.error("Unable to start the gRPC server, still not listening after 1 minute");
249	        } catch (ExecutionException e) {
250	            LOGGER.error("Unable to start the gRPC server", e.getCause());
251	        }
252	    }
