93	    public void initializeGrpcServer(RuntimeValue<Vertx> vertxSupplier,
94	            RuntimeValue<Router> routerSupplier,
95	            GrpcConfiguration cfg,
96	            ShutdownContext shutdown,
97	            Map<String, List<String>> blockingMethodsPerService,
98	            Map<String, List<String>> virtualMethodsPerService,
99	            LaunchMode launchMode, boolean securityPresent) {
100	        GrpcContainer grpcContainer = Arc.container().instance(GrpcContainer.class).get();
101	        if (grpcContainer == null) {
102	            throw new IllegalStateException("gRPC not initialized, GrpcContainer not found");
103	        }
104	        if (hasNoServices(grpcContainer.getServices()) && LaunchMode.current() != LaunchMode.DEVELOPMENT) {
105	            LOGGER.error("Unable to find beans exposing the `BindableService` interface - not starting the gRPC server");
106	            return; // OK?
107	        }
108	
109	        Vertx vertx = vertxSupplier.getValue();
110	        GrpcServerConfiguration configuration = cfg.server;
111	        GrpcBuilderProvider<?> provider = GrpcBuilderProvider.findServerBuilderProvider(configuration);
112	
113	        if (configuration.useSeparateServer) {
114	            if (provider == null) {
115	                LOGGER.warn(
116	                        "Using legacy gRPC support, with separate new HTTP server instance. " +
117	                                "Switch to single HTTP server instance usage with quarkus.grpc.server.use-separate-server=false property");
118	            }
119	
120	            if (launchMode == LaunchMode.DEVELOPMENT) {
121	                // start single server, not in a verticle, regardless of the configuration.instances
122	                // for reason unknown to me, verticles occasionally get undeployed on dev mode reload
123	                if (GrpcServerReloader.getServer() != null || (provider != null && provider.serverAlreadyExists())) {
124	                    devModeReload(grpcContainer, vertx, configuration, provider, blockingMethodsPerService,
125	                            virtualMethodsPerService, shutdown);
126	                } else {
127	                    devModeStart(grpcContainer, vertx, configuration, provider, blockingMethodsPerService,
128	                            virtualMethodsPerService, shutdown,
129	                            launchMode);
130	                }
131	            } else {
132	                prodStart(grpcContainer, vertx, configuration, provider, blockingMethodsPerService, virtualMethodsPerService,
133	                        launchMode);
134	            }
135	        } else {
136	            buildGrpcServer(vertx, configuration, routerSupplier, shutdown, blockingMethodsPerService, virtualMethodsPerService,
137	                    grpcContainer, launchMode, securityPresent);
138	        }
139	    }
