142	    private void buildGrpcServer(Vertx vertx, GrpcServerConfiguration configuration, RuntimeValue<Router> routerSupplier,
143	            ShutdownContext shutdown, Map<String, List<String>> blockingMethodsPerService,
144	            Map<String, List<String>> virtualMethodsPerService,
145	            GrpcContainer grpcContainer, LaunchMode launchMode, boolean securityPresent) {
146	
147	        GrpcServer server = GrpcServer.server(vertx);
148	        List<ServerInterceptor> globalInterceptors = grpcContainer.getSortedGlobalInterceptors();
149	
150	        if (launchMode == LaunchMode.DEVELOPMENT) {
151	            // add as last, so they will run first
152	            globalInterceptors.add(new DevModeInterceptor(Thread.currentThread().getContextClassLoader()));
153	            globalInterceptors.add(new GrpcHotReplacementInterceptor());
154	        }
155	
156	        List<GrpcServiceDefinition> toBeRegistered = collectServiceDefinitions(grpcContainer.getServices());
157	        List<ServerServiceDefinition> definitions = new ArrayList<>();
158	
159	        CompressionInterceptor compressionInterceptor = prepareCompressionInterceptor(configuration);
160	
161	        for (GrpcServiceDefinition service : toBeRegistered) {
162	            ServerServiceDefinition defWithInterceptors = serviceWithInterceptors(
163	                    vertx, grpcContainer, blockingMethodsPerService, virtualMethodsPerService, compressionInterceptor, service,
164	                    launchMode == LaunchMode.DEVELOPMENT);
165	            LOGGER.debugf("Registered gRPC service '%s'", service.definition.getServiceDescriptor().getName());
166	            ServerServiceDefinition serviceDefinition = ServerInterceptors.intercept(defWithInterceptors, globalInterceptors);
167	            GrpcServiceBridge bridge = GrpcServiceBridge.bridge(serviceDefinition);
168	            bridge.bind(server);
169	            definitions.add(service.definition);
170	        }
171	
172	        boolean reflectionServiceEnabled = configuration.enableReflectionService || launchMode == LaunchMode.DEVELOPMENT;
173	
174	        if (reflectionServiceEnabled) {
175	            LOGGER.info("Registering gRPC reflection service");
176	            ReflectionServiceV1 reflectionServiceV1 = new ReflectionServiceV1(definitions);
177	            ReflectionServiceV1alpha reflectionServiceV1alpha = new ReflectionServiceV1alpha(definitions);
178	            ServerServiceDefinition serviceDefinition = ServerInterceptors.intercept(reflectionServiceV1, globalInterceptors);
179	            GrpcServiceBridge bridge = GrpcServiceBridge.bridge(serviceDefinition);
180	            bridge.bind(server);
181	            ServerServiceDefinition serviceDefinitionAlpha = ServerInterceptors.intercept(reflectionServiceV1alpha,
182	                    globalInterceptors);
183	            GrpcServiceBridge bridgeAlpha = GrpcServiceBridge.bridge(serviceDefinitionAlpha);
184	            bridgeAlpha.bind(server);
185	        }
186	
187	        initHealthStorage();
188	
189	        LOGGER.info("Starting new Quarkus gRPC server (using Vert.x transport)...");
190	        Route route = routerSupplier.getValue().route().handler(ctx -> {
191	            if (!isGrpc(ctx)) {
192	                ctx.next();
193	            } else {
194	                if (securityPresent) {
195	                    GrpcSecurityInterceptor.propagateSecurityIdentityWithDuplicatedCtx(ctx);
196	                }
197	                if (!Context.isOnEventLoopThread()) {
198	                    Context capturedVertxContext = Vertx.currentContext();
199	                    if (capturedVertxContext != null) {
200	                        capturedVertxContext.runOnContext(new Handler<Void>() {
201	                            @Override
202	                            public void handle(Void unused) {
203	                                server.handle(ctx.request());
204	                            }
205	                        });
206	                        return;
207	                    }
208	                }
209	                server.handle(ctx.request());
210	            }
211	        });
212	        shutdown.addShutdownTask(route::remove); // remove this route at shutdown, this should reset it
213	
214	        initHealthStorage();
215	    }
